<?php
require_once __DIR__ . '/../lib/bootstrap.php'; require_role('teacher','admin');$uid=(int)current_user()['id'];$where=current_user()['role']==='admin'?'1=1':'e.created_by='.$uid;$stmt=db()->query("SELECT e.*,s.title subject_title,c.title class_title,(SELECT COUNT(*) FROM questions q WHERE q.exam_id=e.id) question_count,(SELECT COUNT(*) FROM attempts a WHERE a.exam_id=e.id) attempt_count FROM exams e JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id WHERE $where ORDER BY e.id DESC");$exams=$stmt->fetchAll();$title='پنل معلم';require __DIR__.'/../partials/header.php';?><div class="teacher-hero"><div><span class="eyebrow">مرکز مدیریت آموزشی</span><h1>سلام، <?=e(current_user()['full_name'])?></h1><p>آزمون‌ها، پرسش‌ها و نتایج کلاس‌ها را حرفه‌ای مدیریت کنید.</p></div><div class="hero-mark">آموزش</div></div><div class="role-stat-grid"><div class="role-stat-card teacher-stat-main teacher-stat-exams"><span class="teacher-stat-icon" aria-hidden="true"></span><span class="teacher-stat-label">کل آزمون‌ها</span><strong><?=number_format(count($exams))?></strong><small>آزمون‌های شما</small></div><div class="role-stat-card teacher-stat-published"><span class="teacher-stat-icon" aria-hidden="true"></span><span class="teacher-stat-label">منتشرشده</span><strong><?=number_format(count(array_filter($exams,fn($e)=>$e['status']==='published'))) ?></strong><small>در دسترس دانش‌آموزان</small></div><div class="role-stat-card teacher-stat-questions"><span class="teacher-stat-icon" aria-hidden="true"></span><span class="teacher-stat-label">پرسش‌ها</span><strong><?=number_format(array_sum(array_map(fn($e)=>(int)$e['question_count'],$exams)))?></strong><small>مجموع پرسش‌ها</small></div><div class="role-stat-card teacher-stat-attempts"><span class="teacher-stat-icon" aria-hidden="true"></span><span class="teacher-stat-label">پاسخ‌ها</span><strong><?=number_format(array_sum(array_map(fn($e)=>(int)$e['attempt_count'],$exams)))?></strong><small>تلاش‌های ثبت‌شده</small></div></div><div class="teacher-actions"><a class="teacher-action-card teacher-action-exams" href="<?=e(url('teacher/exams.php'))?>"><span class="action-icon" aria-hidden="true"></span><h3>ساخت آزمون جدید</h3><p>ساخت آزمون برای کلاس‌های منتسب</p><b>شروع ساخت ←</b></a><a class="teacher-action-card teacher-action-bank" href="<?=e(url('teacher/question_bank.php'))?>"><span class="action-icon" aria-hidden="true"></span><h3>بانک سؤال</h3><p>ذخیره و استفادهٔ مجدد از پرسش‌ها</p><b>مشاهده بانک ←</b></a><a class="teacher-action-card teacher-action-feedback" href="<?=e(url('teacher/feedback.php'))?>"><span class="action-icon" aria-hidden="true"></span><h3>بازخورد دانش‌آموزان</h3><p>ثبت برنامهٔ تمرینی و نکات آموزشی</p><b>ثبت بازخورد ←</b></a></div><div class="section-heading role-section-heading"><div><span class="eyebrow">مدیریت آزمون‌ها</span><h2>آزمون‌های اخیر</h2></div><a class="btn btn-light btn-sm" href="<?=e(url('teacher/exams.php'))?>">آزمون جدید</a></div><div class="teacher-exam-grid"><?php if(!$exams):?><div class="empty-card"><h3>هنوز آزمونی ساخته نشده است</h3><p class="muted">اولین آزمون خود را ایجاد کنید.</p><a class="btn btn-primary" href="<?=e(url('teacher/exams.php'))?>">ساخت آزمون</a></div><?php else:foreach($exams as $exam):?><article class="teacher-exam-card"><div class="exam-card-top"><span class="exam-chip"><?=e($exam['subject_title'])?></span><span class="badge <?= $exam['status']==='published'?'success':'warning' ?>"><?=e($exam['status'])?></span></div><h3><?=e($exam['title'])?></h3><p class="muted"><?=e($exam['class_title'])?></p><div class="exam-meta"><span><?=e((string)$exam['question_count'])?> پرسش</span><span><?=e((string)$exam['attempt_count'])?> پاسخ</span></div><div class="actions"><a class="btn btn-sm btn-primary" href="<?=e(url('teacher/exams.php?id='.$exam['id']))?>">مدیریت</a><a class="btn btn-sm btn-light" href="<?=e(url('teacher/results.php?exam_id='.$exam['id']))?>">نتایج</a><?php if($exam['status']==='draft'):?><form method="post" action="<?=e(url('teacher/exams.php'))?>" style="display:inline" onsubmit="return confirm('آزمون پیش‌نویس حذف شود؟ این عملیات قابل بازگشت نیست.')"><?=csrf_field()?><input type="hidden" name="action" value="delete_exam"><input type="hidden" name="exam_id" value="<?=$exam['id']?>"><button class="btn btn-sm btn-danger" type="submit">حذف آزمون</button></form><?php endif;?></div></article><?php endforeach;endif;?></div><?php require __DIR__.'/../partials/footer.php'; ?>
